<script setup>
defineProps({
  confirmingEntry: { type: Object, default: null }, confirmingDebt: { type: Object, default: null }, debtDetailType: { type: String, default: null }, visibleDebtDetails: { type: Array, required: true }, debtModalOpen: { type: Boolean, required: true }, debtInput: { type: String, required: true }, debtNote: { type: String, required: true }, debtDirection: { type: Number, required: true }, debtType: { type: String, required: true }, tagModalOpen: { type: Boolean, required: true }, tagInput: { type: String, required: true }, tags: { type: Array, required: true }, editingTagId: { type: String, default: null }, editingTagName: { type: String, required: true }, detailTitle: { type: String, required: true }, paginatedDetailRows: { type: Array, required: true }, detailRows: { type: Array, required: true }, detailPage: { type: Number, required: true }, detailTotalPages: { type: Number, required: true }, detailVisibleRange: { type: String, required: true }, pageSize: { type: Number, required: true }, selectedEntryDetail: { type: Object, default: null }, balancesHidden: { type: Boolean, required: true }, error: { type: String, required: true }, formatAmount: { type: Function, required: true }, formatTime: { type: Function, required: true }, accountLabel: { type: Function, required: true }
})
defineEmits(['cancel-remove', 'confirm-remove', 'cancel-remove-debt', 'confirm-remove-debt', 'close-debt-details', 'request-remove-debt', 'close-debt-modal', 'submit-debt', 'update:debt-input', 'update:debt-note', 'update:debt-direction', 'update:debt-type', 'close-tag-modal', 'submit-tag', 'update:tag-input', 'start-tag-edit', 'save-tag', 'cancel-tag-edit', 'update:editing-tag-name', 'remove-tag', 'close-details', 'open-entry-detail', 'update:detail-page', 'close-entry-detail'])
</script>

<template>
  <div v-if="confirmingEntry" class="dialog-backdrop" @click.self="$emit('cancel-remove')"><section class="confirm-dialog" role="alertdialog" aria-modal="true"><h2>Xoá giao dịch?</h2><p>{{ confirmingEntry.note || 'Giao dịch không có ghi chú' }} · {{ confirmingEntry.amount < 0 ? '' : '+' }}{{ formatAmount(confirmingEntry.amount) }}. Thao tác này không thể hoàn tác.</p><div class="dialog-actions"><button type="button" class="cancel-delete-btn" @click="$emit('cancel-remove')">Huỷ</button><button type="button" class="confirm-delete-btn" @click="$emit('confirm-remove')">Xoá</button></div></section></div>
  <div v-if="confirmingDebt" class="dialog-backdrop" @click.self="$emit('cancel-remove-debt')"><section class="confirm-dialog debt-confirm-dialog" role="alertdialog" aria-modal="true"><h2>Thanh toán khoản nợ?</h2><p>{{ confirmingDebt.note || 'Khoản nợ không có ghi chú' }} · {{ confirmingDebt.amount < 0 ? '' : '+' }}{{ formatAmount(confirmingDebt.amount) }}. {{ confirmingDebt.debt_type === 'lent' ? 'Tiền sẽ được cộng vào Tài khoản' : 'Tiền sẽ được trừ khỏi Tài khoản' }} và không tính vào thu nhập ngày.</p><div class="dialog-actions"><button type="button" class="cancel-delete-btn" @click="$emit('cancel-remove-debt')">Huỷ</button><button type="button" class="confirm-delete-btn" @click="$emit('confirm-remove-debt')">Thanh toán</button></div></section></div>
  <div v-if="debtDetailType" class="dialog-backdrop" @click.self="$emit('close-debt-details')"><section class="confirm-dialog debt-details-dialog" role="dialog" aria-modal="true"><div class="debt-details-heading"><h2>{{ debtDetailType === 'lent' ? 'Người khác đang nợ tôi' : 'Nợ hiện tại' }}</h2><button type="button" class="close-details-btn" aria-label="Đóng" @click="$emit('close-debt-details')">×</button></div><p>{{ visibleDebtDetails.length ? 'Chạm vào một dòng để thanh toán khoản nợ.' : 'Chưa có khoản nào.' }}</p><div v-if="visibleDebtDetails.length" class="debt-list debt-details-list"><button v-for="debt in visibleDebtDetails" :key="debt.id" type="button" class="debt-row" @click="$emit('request-remove-debt', debt)"><span class="debt-date">{{ new Date(debt.created_at).toLocaleDateString('vi-VN') }}</span><span class="debt-note">{{ debt.note || '—' }}</span><span class="debt-amount">{{ debt.amount < 0 ? '' : '+' }}{{ formatAmount(debt.amount) }}</span></button></div></section></div>
  <div v-if="debtModalOpen" class="dialog-backdrop" @click.self="$emit('close-debt-modal')"><section class="confirm-dialog debt-entry-dialog" role="dialog" aria-modal="true"><div class="debt-details-heading"><h2>Ghi khoản nợ</h2><button type="button" class="close-details-btn" aria-label="Đóng" @click="$emit('close-debt-modal')">×</button></div><form class="debt-form debt-modal-form" @submit.prevent="$emit('submit-debt')"><label class="debt-field-label" for="debt-amount">Số tiền</label><input id="debt-amount" :value="debtInput" class="amount-input" type="text" inputmode="numeric" placeholder="Số tiền nợ" autofocus @input="$emit('update:debt-input', $event.target.value)" /><label class="debt-field-label" for="debt-note">Ghi chú</label><input id="debt-note" :value="debtNote" class="note-input" type="text" placeholder="Ghi chú nợ (tuỳ chọn)" @input="$emit('update:debt-note', $event.target.value)" /><div class="amount-direction"><button type="button" :class="{ active: debtType === 'owed' }" @click="$emit('update:debt-type', 'owed')">Tôi đang nợ</button><button type="button" :class="{ active: debtType === 'lent' }" @click="$emit('update:debt-type', 'lent')">Cho người khác nợ</button></div><div class="amount-direction"><button type="button" :class="{ active: debtDirection === 1 }" @click="$emit('update:debt-direction', 1)">+ Phát sinh</button><button type="button" :class="{ active: debtDirection === -1 }" @click="$emit('update:debt-direction', -1)">− Thu hồi / trả</button></div><p v-if="error" class="debt-modal-error">{{ error }}</p><div class="dialog-actions"><button type="button" class="cancel-delete-btn" @click="$emit('close-debt-modal')">Huỷ</button><button type="submit" class="confirm-delete-btn debt-submit-btn">Ghi nợ</button></div></form></section></div>
  <div v-if="tagModalOpen" class="dialog-backdrop" @click.self="$emit('close-tag-modal')"><section class="confirm-dialog tag-dialog" role="dialog" aria-modal="true"><div class="debt-details-heading"><h2>Quản lý thẻ</h2><button type="button" class="close-details-btn" aria-label="Đóng" @click="$emit('close-tag-modal')">×</button></div><form class="tag-add-form" @submit.prevent="$emit('submit-tag')"><input :value="tagInput" class="note-input" type="text" placeholder="Tên thẻ mới" @input="$emit('update:tag-input', $event.target.value)" /><button type="submit" class="save-balance-btn">Thêm</button></form><p v-if="error" class="debt-modal-error">{{ error }}</p><div class="tag-list"><div v-for="tag in tags" :key="tag.id" class="tag-list-row"><template v-if="editingTagId === tag.id"><input :value="editingTagName" class="note-input" type="text" @input="$emit('update:editing-tag-name', $event.target.value)" @keyup.enter="$emit('save-tag', tag)" /><button type="button" class="tag-action-btn" @click="$emit('save-tag', tag)">Lưu</button><button type="button" class="tag-action-btn" @click="$emit('cancel-tag-edit')">Huỷ</button></template><template v-else><span>{{ tag.name }}</span><button type="button" class="tag-action-btn" @click="$emit('start-tag-edit', tag)">Sửa</button><button type="button" class="tag-action-btn tag-delete-btn" @click="$emit('remove-tag', tag)">Xoá</button></template></div></div></section></div>
  <div v-if="detailTitle" class="dialog-backdrop" @click.self="$emit('close-details')"><section class="confirm-dialog detail-dialog" role="dialog" aria-modal="true"><div class="debt-details-heading"><h2>{{ detailTitle }}</h2><button type="button" class="close-details-btn" aria-label="Đóng" @click="$emit('close-details')">×</button></div><div class="detail-list"><button v-for="row in paginatedDetailRows" :key="row.id" type="button" class="row" @click="$emit('open-entry-detail', row)"><span class="row-note">{{ row.note || '—' }} <span class="row-meta"><span class="account-badge">{{ accountLabel(row.account_type) }}</span><span v-if="row.tag" class="tag-badge">{{ row.tag }}</span><span v-if="row.counts_toward_daily === false" class="daily-excluded-badge">Không tính ngày</span></span></span><span class="row-time">{{ formatTime(row.created_at) }}</span><span class="row-amount" :class="row.amount < 0 ? 'neg' : 'pos'">{{ row.amount < 0 ? '' : '+' }}{{ formatAmount(row.amount) }}</span><span class="row-balance" :class="{ masked: balancesHidden }">{{ balancesHidden ? '••••••' : formatAmount(row.accountBalance) }}</span></button></div><nav v-if="detailRows.length > pageSize" class="pagination"><span>{{ detailVisibleRange }}</span><div class="pagination-controls"><button type="button" :disabled="detailPage === 1" @click="$emit('update:detail-page', detailPage - 1)">Trước</button><span>{{ detailPage }} / {{ detailTotalPages }}</span><button type="button" :disabled="detailPage === detailTotalPages" @click="$emit('update:detail-page', detailPage + 1)">Sau</button></div></nav></section></div>
  <div v-if="selectedEntryDetail" class="dialog-backdrop" @click.self="$emit('close-entry-detail')"><section class="confirm-dialog entry-detail-dialog" role="dialog" aria-modal="true"><div class="debt-details-heading"><h2>Chi tiết giao dịch</h2><button type="button" class="close-details-btn" aria-label="Đóng" @click="$emit('close-entry-detail')">×</button></div><p class="entry-detail-amount" :class="selectedEntryDetail.amount < 0 ? 'neg' : 'pos'">{{ selectedEntryDetail.amount < 0 ? '' : '+' }}{{ formatAmount(selectedEntryDetail.amount) }} ₫</p><p class="entry-detail-note">{{ selectedEntryDetail.note || 'Không có ghi chú' }}</p></section></div>
</template>
